package com.energie.platform.controller;
import com.energie.platform.dto.Dtos.*; import com.energie.platform.service.RendezVousService; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/rendez-vous") @Tag(name="Public - Rendez-vous") @RequiredArgsConstructor public class RendezVousController {private final RendezVousService service;
 @GetMapping("/creneaux-disponibles") @Operation(summary="Lister les créneaux de rendez-vous libres") public List<String> creneauxDisponibles(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date){return service.creneauxDisponibles(date);}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Planifier un rendez-vous") public RendezVousResponse planifier(@Valid @RequestBody RendezVousCreationRequest r){return service.planifier(r);}}
